	"golive__tip_broadcaster_1": "<b>TIPS:</b> Tack för att du sänder live! Välkomna folk genom att hälsa på dem när de börjar titta.",
	"golive__tip_broadcaster_10": "<b>TIPS:</b> Tack för att du sänder live på X! ≺3",
	"golive__tip_broadcaster_2": "<b>TIPS:</b> Försök nämna folk vid namn när de börjar titta på din livesändning – det gillar de!",
	"golive__tip_broadcaster_3": "<b>TIPS:</b> Börja sända live ett par minuter innan du har tänkt börja så att det blir lättare för folk att hitta dig.",
	"golive__tip_broadcaster_4": "<b>TIPS:</b> Fråga tittarna varifrån de kommer – det är ett bra sätt att få igång samtalet.",
	"golive__tip_broadcaster_5": "<b>TIPS:</b> Tacka folk för att de tittar och besvara deras kommentarer så att de fortsätter att titta.",
	"golive__tip_broadcaster_6": "<b>TIPS:</b> Om du förlorar uppkopplingen när du sänder kan du bege dig någonstans där signalen är bättre.",
	"golive__tip_broadcaster_7": "<b>TIPS:</b> Be folk att följa dig så att de får en notis nästa gång du sänder live.",
	"golive__tip_broadcaster_8": "<b>TIPS:</b> Inled livesändningen med att säga hej. Folk som tittar i efterhand gillar det.",
	"golive__tip_broadcaster_9": "<b>TIPS:</b> Tacka folk för att de har tittat innan du avslutar livesändningen.",
	"golive__tip_pre_broadcast_1": "<b>TIPS:</b> Skriv en titel innan du börjar sända live så att folk lättare hittar din video.",
	"golive__tip_pre_broadcast_2": "<b>TIPS:</b> En beskrivande titel hjälper folk att förstå vad din livesändning handlar om.",
	"golive__tip_pre_broadcast_3": "<b>TIPS:</b> Behöver du uppslag? Visa folk runt, visa vad du är bra på eller prata om något du är intresserad av.",
	"golive__tip_pre_broadcast_4": "<b>TIPS:</b> Se till att du har en stark signal till telefonen innan du börjar sända live.",
	"golive__tip_pre_broadcast_5": "<b>TIPS:</b> Lägg till en hashtagg i rubriken så att folk lättare hittar din livesändning.",
	"golive__tip_pre_broadcast_6": "<b>TIPS:</b> Det var allt vi hade att bjuda på för tillfället – tack för att du sänder live på X!",
