	"identity_education_conditions": "Jag går med på att X och Au10tix använder bilder av mitt id och min selfie, däribland extraherade biometriska data, för att bekräfta min identitet och för X:s relaterade säkerhetssyften, bland annat för att förhindra uppträdande under falsk identitet. Au10tix kan lagra sådana data i upp till 30 dagar. {{}}Läs mer{{}}",
