	"identity_education_conditions_eea": "\"Jag går med på att X överlämnar bilder av mitt id, däribland biometriska data, och personuppgifter från min profil till Au10tix i syfte att bekräfta min identitet.\nJag går även med på att X lagrar mina id-bilder, däribland biometriska data, i upp till 30 dagar och använder dem och uppgifter från min profil i säkerhetssyfte, däribland för att förhindra uppträdande under falsk identitet. {{}}Läs mer{{}}\"",
	"identity_education_conditions_persona_vendor": "Jag godkänner att X och Persona får använda bilder av mitt id och min selfie, däribland extraherade biometriska data, för att bekräfta min identitet och för X:s relaterade säkerhet och skydd, bedrägeriskydd och betalningsändamål. Persona kan lagra dessa data i upp till 30 dagar. X kan lagra det fullständigt namnet, adressen och hashar av mitt dokument-id-nummer så länge som jag prenumererar på X Premium-tjänsten. {{}}Läs mer{{}}",
